  makeBox(group,-4.65,.65,5.7,1.1,1.2,3.8,materials.tire);
  makeBox(group,4.65,.65,5.7,1.1,1.2,3.8,materials.tire);
  const ob={kind,name,x,z,heading:kind==='TRAFFIC'?(axis==='x'?(dir>0?Math.PI/2:-Math.PI/2):(dir>0?Math.PI:0)):0,speed,group,axis,dir,parked:kind==='CAR',damage:0};
  group.position.set(x,0,z);group.rotation.y=ob.heading;cars.push(ob);return ob;
}
