@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#071212;--glass:rgba(7,18,19,.78);--line:rgba(203,233,220,.15);--mint:#a6f2c5;--muted:#9aaba7}
*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--ink);font-family:Manrope,system-ui,sans-serif;color:#f3f5ef}
button{font:inherit}
.game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#66756a}
#game{position:absolute;inset:0;width:100%;height:100%;display:block}
.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(5,14,15,.3),transparent 25%,transparent 73%,rgba(4,12,12,.32));box-shadow:inset 0 0 130px rgba(0,0,0,.2)}
.topbar{position:absolute;z-index:2;top:0;left:0;right:0;height:74px;padding:0 36px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(5,15,16,.78),rgba(5,15,16,.08));}
.brand{display:flex;align-items:center;gap:12px}
.brand-mark{width:37px;height:37px;border:1px solid rgba(166,242,197,.55);border-radius:11px;display:grid;place-items:center;color:var(--mint);font-size:11px;font-weight:800;letter-spacing:-.7px}
.brand b{display:block;font-size:12px;letter-spacing:2px}
.brand small{display:block;margin-top:3px;color:#a8b7b1;font:9px 'DM Mono',monospace;letter-spacing:1.1px}
.district{font:10px 'DM Mono',monospace;letter-spacing:1.6px;color:#e3eae3}
.district i{font-style:normal;color:#81908a;margin:0 10px}
.live-dot,.tiny-dot{display:inline-block;width:6px;height:6px;background:#a5f2c4;border-radius:50%;box-shadow:0 0 12px #a5f2c4;margin-right:8px}
.top-right{display:flex;align-items:center;gap:20px;font:9px 'DM Mono',monospace;letter-spacing:1px;color:#c2d0c8}
.profile{display:grid;place-items:center;width:32px;height:32px;border-radius:50%;border:1px solid var(--line);font:10px Manrope,sans-serif;color:#eaf1e9}
.mission-card,.status-card,.minimap-card{position:absolute;z-index:2;background:var(--glass);border:1px solid var(--line);backdrop-filter:blur(16px);box-shadow:0 12px 35px rgba(0,0,0,.16)}
.mission-card{top:96px;left:36px;width:300px;min-height:84px;border-radius:13px;display:flex;align-items:center;padding:15px 14px;gap:13px}
.mission-icon{width:34px;height:34px;display:grid;place-items:center;border-radius:9px;background:rgba(166,242,197,.12);color:var(--mint);font-size:17px}
.mission-card small{display:block;font:8px 'DM Mono',monospace;letter-spacing:1.3px;color:#9eb2a7;margin-bottom:5px}
.mission-card strong{display:block;font-size:12px;font-weight:700}
.mission-card span{display:block;color:#a6b3ac;font-size:10px;margin-top:3px}
.mission-card button{align-self:flex-start;margin-left:auto;border:0;background:none;color:#b1beb7;font-size:19px;cursor:pointer}
.status-card{top:96px;right:36px;width:210px;border-radius:12px;padding:14px 15px}
.status-label{font:9px 'DM Mono',monospace;letter-spacing:1.2px;margin-bottom:12px}
.status-live{float:right;color:var(--mint);font-size:8px}
.status-row{display:flex;align-items:center;justify-content:space-between;margin-top:8px;font:8px 'DM Mono',monospace;letter-spacing:.6px;color:#98aaa1}
.status-row b{font-size:9px;color:#dce7dc;font-weight:500;letter-spacing:2px}
.status-row:nth-child(3) b{color:#f5ce92;letter-spacing:2px}
.minimap-card{right:36px;bottom:72px;width:190px;height:225px;border-radius:13px;padding:5px 5px 7px;overflow:hidden}
.minimap-card canvas{display:block;width:178px;height:178px;border-radius:9px}
.map-label{display:flex;justify-content:space-between;padding:1px 5px 0;font:8px 'DM Mono',monospace;letter-spacing:1.2px;color:#dce8df}
.map-label span{color:var(--mint)}
.map-coords{text-align:center;margin-top:3px;font:7px 'DM Mono',monospace;color:#91a49a}
.speed-card{position:absolute;z-index:2;left:36px;bottom:82px;width:210px;padding:0 0 0 2px;opacity:0;transform:translateY(8px);transition:.25s;pointer-events:none}
.speed-card.show{opacity:1;transform:none}
.speed-value{display:flex;align-items:baseline;gap:8px}
.speed-value b{font-size:42px;line-height:1;font-weight:500;letter-spacing:-3px}
.speed-value small{font:9px 'DM Mono',monospace;letter-spacing:1px;color:#c1cec5}
.speed-meter{height:3px;background:rgba(245,255,247,.25);width:180px;margin:10px 0 8px;border-radius:4px;overflow:hidden}
.speed-meter i{display:block;width:0;height:100%;background:var(--mint);transition:width .15s}
.vehicle-tag{font:8px 'DM Mono',monospace;letter-spacing:1.3px;color:#d3ded5}
.vehicle-tag span{color:var(--mint);margin-left:7px}
.controls{position:absolute;z-index:2;left:50%;bottom:23px;transform:translateX(-50%);display:flex;align-items:center;gap:23px;padding:9px 14px;background:rgba(6,17,17,.67);border:1px solid rgba(220,240,223,.12);border-radius:8px;white-space:nowrap;backdrop-filter:blur(12px)}
.control-hint{display:flex;align-items:center;gap:4px}
.control-hint span{margin-left:5px;font:8px 'DM Mono',monospace;letter-spacing:.65px;color:#c0cec3}
.control-hint kbd,.interaction kbd{font:9px 'DM Mono',monospace;min-width:17px;height:18px;padding:2px 4px;display:grid;place-items:center;color:#e4ede3;background:rgba(225,245,230,.12);border:1px solid rgba(225,245,230,.16);border-radius:3px}
.interaction{position:absolute;z-index:3;display:none;align-items:center;gap:8px;padding:7px 10px;border-radius:6px;background:rgba(6,18,17,.84);border:1px solid rgba(208,238,218,.24);font:8px 'DM Mono',monospace;letter-spacing:1px;color:white;pointer-events:none}
.interaction.show{display:flex}
.interaction kbd{color:#092016;background:var(--mint);border-color:var(--mint);font-weight:bold}
.toast{position:absolute;z-index:4;left:50%;top:25%;transform:translate(-50%,-6px);padding:10px 16px;border:1px solid rgba(198,235,207,.2);background:rgba(5,17,17,.84);border-radius:7px;color:#e8f4e9;font:9px 'DM Mono',monospace;letter-spacing:1px;opacity:0;transition:.25s;pointer-events:none}
.toast.show{opacity:1;transform:translate(-50%,0)}
.phone{position:absolute;z-index:5;right:45px;top:50%;width:258px;height:470px;padding:16px;border-radius:29px;background:#101917;border:2px solid rgba(222,239,225,.42);box-shadow:0 25px 100px #000b;transform:translate(350px,-50%) rotate(5deg);transition:transform .35s cubic-bezier(.2,.8,.2,1);pointer-events:none}
.phone.open{transform:translate(0,-50%) rotate(0);pointer-events:auto}
.phone-notch{position:absolute;z-index:2;top:9px;left:50%;transform:translateX(-50%);width:73px;height:17px;border-radius:20px;background:#0b100f}
.phone-head{height:28px;display:flex;justify-content:space-between;padding:2px 5px;font:9px 'DM Mono',monospace}
.phone-brand{padding:9px 2px 12px;font-size:10px;letter-spacing:2px}
.phone-brand b{color:#9df2bb}
.phone-screen{height:335px;border-radius:17px;padding:21px 16px;background:linear-gradient(155deg,#dee9d9,#b6ceb9);color:#163026}
.phone-greeting{font-size:21px;line-height:1.3;letter-spacing:-.8px}
.phone-greeting b{font-weight:800}
.phone-weather{font:9px 'DM Mono',monospace;margin-top:13px;padding:10px;border-radius:8px;background:#ffffff75}
.phone-apps{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:17px}
.phone-apps button{height:72px;border:0;border-radius:10px;background:#f6faf1;color:#365142;font:8px 'DM Mono',monospace;letter-spacing:.6px;cursor:pointer}
.phone-apps i{display:block;font:23px Manrope,sans-serif;color:#267347;margin-bottom:4px}
.phone-tip{margin-top:14px;padding:10px;border-radius:9px;background:#f1f7eb;font:8px 'DM Mono',monospace}
.phone-tip span{float:right}
.phone-tip small{display:block;margin-top:7px;line-height:1.5;color:#64776b;font:9px Manrope,sans-serif}
.phone-home{text-align:center;margin-top:16px;color:#aab8ad;font:8px 'DM Mono',monospace}
.start-overlay{position:absolute;z-index:8;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,rgba(3,14,14,.62),rgba(3,14,14,.08) 80%),linear-gradient(0deg,rgba(4,12,12,.45),transparent 50%);transition:opacity .7s,visibility .7s}
.start-overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}
.start-panel{position:absolute;left:10%;top:50%;transform:translateY(-46%);width:370px}
.start-eyebrow{font:9px 'DM Mono',monospace;letter-spacing:2.5px;color:var(--mint)}
.start-panel h1{margin:22px 0 14px;font-size:72px;line-height:.83;letter-spacing:-6px;font-weight:800}
.start-panel h1 em{font-style:normal;color:var(--mint)}
.start-panel p{font-size:13px;line-height:1.8;color:#c4d2c8}
.start-panel>button{margin-top:18px;width:205px;height:45px;padding:0 15px;border:0;border-radius:5px;background:#a7f0c3;color:#0b2419;font:800 9px 'DM Mono',monospace;letter-spacing:1.1px;cursor:pointer;transition:transform .2s,background .2s}
.start-panel>button:hover{transform:translateY(-2px);background:#c2ffda}
.start-panel>button span{float:right;font-size:16px}
.start-foot{display:flex;gap:20px;margin-top:55px;color:#9daea4;font:8px 'DM Mono',monospace;letter-spacing:1px}
.start-credit{position:absolute;bottom:26px;right:38px;color:#c2cfc5;font:8px 'DM Mono',monospace;letter-spacing:1.4px}
@media(max-width:720px){.topbar{padding:0 17px;height:60px}
.district{display:none}
.top-right{gap:10px}
.mission-card{left:15px;top:76px;width:min(270px,calc(100vw - 30px))}
.status-card{display:none}
.minimap-card{right:14px;bottom:70px;width:147px;height:178px;padding:4px}
.minimap-card canvas{width:137px;height:137px}
.map-coords{font-size:6px}
.speed-card{left:18px;bottom:83px;width:150px}
.speed-value b{font-size:35px}
.speed-meter{width:130px}
.controls{bottom:12px;gap:8px;padding:7px 8px}
.control-hint span{font-size:6px;margin-left:2px}
.control-hint kbd{min-width:15px;height:16px;font-size:8px}
.control-hint:nth-child(3){display:none}
.start-panel{left:8%;width:300px}
.start-panel h1{font-size:62px}
.start-credit{right:12px;bottom:14px;font-size:6px}
.phone{right:20px;transform:translate(310px,-50%) scale(.9)}
.phone.open{transform:translate(0,-50%) scale(.9)}
}
@media(max-height:560px){.mission-card{top:78px}
.start-panel{top:47%}
.start-panel h1{font-size:57px;margin:14px 0}
.start-foot{margin-top:25px}
.phone{height:420px}
.phone-screen{height:290px}
}

